import React, { useEffect, useState } from 'react'
import AdaptableCard from 'components/shared/AdaptableCard'
import NumberFormat from 'react-number-format'
import StickyFooter from 'components/shared/StickyFooter'
import Button from 'components/ui/Buttons'
import toast from 'components/ui/toast'
import Notification from 'components/ui/Notification'
import './AddEditFinanceVoucher.css'
import {
    apiFinanceVoucherApprove,
    apiFinanceVoucherGetSingle,
    apiFinanceVoucherReject,
} from 'services/FinanceVoucherService'
import { useNavigate, useParams } from 'react-router-dom'
import Moment from 'react-moment'
import Loading from 'components/shared/Loading'
import { Input } from 'components/ui'
const AddEditFinanceVoucher = () => {
    const financeVoucherId = useParams()
    const navigate = useNavigate()
    const [pVoucherData, setPVoucherData] = useState({
        id: 0,
        date_of_processing: new Date(),
        vendor_state: '',
        default_state: '',
        vendor_id: 0,
        requestor_id: 0,
        tds_per: 0,
        total_payable: 0,
        final_amount: 0,
        voucher_no: 0,
        invoice_date: new Date(),
        invoice_no: '',
        type_use: '',
        type: '',
        po_no: '',
        attached: '',
        tdsamount: 0,
        po_id: 0,
        po_status: '',
        other_charges_amount: 0,
        other_charges: '',
        po_previous_state: '',
        vendor_name: '',
        gst_in: '',
        tax_type: '',
        pay_immediately: 0,
        raw_material_in_id: 0,
        status: '',
        remark: '',
    })
    const [voucherData, setVoucherData] = useState({
        id: '',
        date_of_receipt: new Date(),
        purchase_order_id: '',
        depot_id: '',
        vendor_id: '',
        tax_type: '',
        amt: '',
        cgst_amt: '',
        sgst_amt: '',
        igst_amt: '',
        tax_amt: '',
        total_amt: '',
        round_off_amt: '',
        final_amount: '',
        gate_pass_no: '',
        raw_material_in_no: '',
        doc_document: '',
        document_name: '',
        partial_po: '',
        invoice_date: '',
        payment_due_date: '',
        pay_immediately: '',
        invoice_no: '',
        status: '',
        remarks: '',
        created_by: '',
        modified_by: '',
        approved_by: '',
        approved_on: '',
        rejected_by: '',
        rejected_on: '',
        ref_id: '',
        created_on: '',
        modified_on: '',
        rawMaterialInItems: [
            {
                id: '',
                raw_material_in_id: '',
                raw_material_id: '',
                hsn_code: '',
                item_desc: '',
                discount: '',
                qty: '',
                rate: '',
                tax_per: '',
                amount: '',
                cgst_amt: '',
                sgst_amt: '',
                igst_amt: '',
                tax_amt: '',
                total_amt: '',
                po_quantity: '',
                po_rate: '',
                po_amount: '',
                po_cgst_amt: '',
                po_sgst_amt: '',
                po_igst_amt: '',
                po_tax_amt: '',
                po_total_amt: '',
                no_of_boxes: '',
                gross_weight: '',
                difference: '',
                po_item_id: '',
                tax_type: '',
                raw_material: {
                    id: '',
                    rm_name: '',
                    hsn_code: '',
                },
            },
        ],
        rawMaterialInOtherCharges: [
            {
                amount: '',
                cgst_amt: '',
                difference: '',
                gross_weight: '',
                hsn_code: '',
                id: '',
                igst_amt: '',
                item_desc: '',
                no_of_boxes: '',
                po_amount: '',
                po_cgst_amt: '',
                po_igst_amt: '',
                po_item_id: '',
                po_quantity: '',
                po_rate: '',
                po_sgst_amt: '',
                po_tax_amt: '',
                po_total_amt: '',
                qty: '',
                rate: '',
                raw_material_id: '',
                raw_material_in_id: '',
                sgst_amt: '',
                tax_amt: '',
                tax_per: '',
                tax_type: '',
                total_amt: '',
            },
        ],
        vendor: {
            id: '',
            vendor_name: '',
            address: '',
            city: '',
            pincode: '',
            state: '',
            country: '',
            gst_number: '',
        },
        depot: {
            id: 2,
            depot_name: '',
            address: '',
            city: '',
            pincode: '',
            state: '',
            country: '',
            gst_no: '',
        },
        created_by_user: {
            id: '',
            first_name: '',
        },
        modified_by_user: {
            id: '',
            first_name: '',
        },
        approved_by_user: {
            id: '',
            first_name: '',
        },
    })
    const [tds, setTds] = useState(0)
    const [roundOff, setRoundOff] = useState(0)
    const [loading, setLoading] = useState(false)

    const approved = async () => {
        console.log(financeVoucherId)
        const values = {
            tds_per: tds,
            round_off_amt: roundOff,
            total_payable: pVoucherData.total_payable,
        }
        await apiFinanceVoucherApprove({
            values,
            ...{ id: financeVoucherId.voucherid },
        })
            .then((data) => {
                console.log(data)
                if (data.status === 200) {
                    toast.push(
                        <Notification title="Success" type="success" closable>
                            {data.data['message']}
                        </Notification>
                    )
                    navigate('/transaction/finance-voucher')
                } else if (data.response.status === 422) {
                    let errorData = data.response['data']['error']['errors']
                    for (const errMsg in errorData) {
                        toast.push(
                            <Notification title="Error" type="danger" closable>
                                {errorData[errMsg]['message']}
                            </Notification>
                        )
                    }
                } else if (data.response.status === 500) {
                    toast.push(
                        <Notification title="Error" type="danger" closable>
                            {data.response.data['message']}
                        </Notification>
                    )
                }
            })
            .catch((error) => {
                let errorData = error.response['data']['error']['errors']
                if (error.response.status === 422) {
                    for (const errMsg in errorData) {
                        toast.push(
                            <Notification title="Error" type="danger" closable>
                                {errorData[errMsg]['message']}
                            </Notification>
                        )
                    }
                } else if (error.response.status === 500) {
                    toast.push(
                        <Notification title="Error" type="danger" closable>
                            {error.response.data['message']}
                        </Notification>
                    )
                }
            })
        return true
    }

    const rejected = async () => {
        const values = {
            tds_per: tds,
            round_off_amt: roundOff,
            total_payable: pVoucherData.total_payable,
        }
        await apiFinanceVoucherReject({
            values,
            ...{ id: financeVoucherId.voucherid },
        })
            .then((data) => {
                console.log(data)
                if (data.status === 200) {
                    toast.push(
                        <Notification title="Success" type="success" closable>
                            {data.data['message']}
                        </Notification>
                    )
                    navigate('/transaction/finance-voucher')
                } else if (data.response.status === 422) {
                    let errorData = data.response['data']['error']['errors']
                    for (const errMsg in errorData) {
                        toast.push(
                            <Notification title="Error" type="danger" closable>
                                {errorData[errMsg]['message']}
                            </Notification>
                        )
                    }
                } else if (data.response.status === 500) {
                    toast.push(
                        <Notification title="Error" type="danger" closable>
                            {data.response.data['message']}
                        </Notification>
                    )
                }
            })
            .catch((error) => {
                let errorData = error.response['data']['error']['errors']
                if (error.response.status === 422) {
                    for (const errMsg in errorData) {
                        toast.push(
                            <Notification title="Error" type="danger" closable>
                                {errorData[errMsg]['message']}
                            </Notification>
                        )
                    }
                } else if (error.response.status === 500) {
                    toast.push(
                        <Notification title="Error" type="danger" closable>
                            {error.response.data['message']}
                        </Notification>
                    )
                }
            })
        return true
    }

    useEffect(() => {
        setLoading(true)
        const fetchData = async () => {
            await apiFinanceVoucherGetSingle(financeVoucherId.voucherid).then(
                (data) => {
                    if (data.status === 200) {
                        console.log(data.data)
                        setVoucherData(data.data.rawMaterialIn)
                        setPVoucherData(data.data.paymentVoucher)
                        setTds(
                            data.data.paymentVoucher.tds_per == null
                                ? 0
                                : data.data.paymentVoucher.tds_per
                        )
                    } else if (data.response.status === 500) {
                        toast.push(
                            <Notification title="Error" type="danger" closable>
                                {data.response.data['message']}
                            </Notification>
                        )
                    }
                    setLoading(false)
                }
            )
        }
        fetchData()
    }, [])

    const calcTDS = (e) => {
        setTds(e.target.value)
        const tds_per = e.target.value
        const amount = voucherData.amt
        const tds_amount = (parseFloat(amount) * parseFloat(tds_per)) / 100

        setPVoucherData((prev) => {
            return { ...prev, tdsamount: tds_amount }
        })
        const roundOff =
            Math.round(
                (Math.round(voucherData.total_amt - tds_amount) -
                    Math.round((voucherData.total_amt - tds_amount) * 100) /
                        100) *
                    100
            ) / 100
        setRoundOff(roundOff)
        const net_amount = voucherData.total_amt - tds_amount + roundOff
        setPVoucherData((prev) => {
            return { ...prev, total_payable: net_amount }
        })
    }
    const calcRoundOff = (e) => {
        const roundOff = parseFloat(e.target.value)
        setRoundOff(e.target.value)
        const tds_amount = parseFloat(pVoucherData.tdsamount)
        console.log(tds_amount)
        console.log(roundOff)
        const net_amount = voucherData.total_amt - tds_amount + roundOff
        // gross_amt - tds_amt + roundOff
        setPVoucherData((prev) => {
            return { ...prev, total_payable: net_amount }
        })
    }

    return (
        <>
            <AdaptableCard className="card-shadow mb-3">
                <Loading loading={loading}></Loading>
                <div
                    className={
                        loading
                            ? 'hidden'
                            : 'visible grid grid-cols-1 lg:grid-cols-2 gap-x-4 gap-y-2'
                    }
                >
                    <div className=" overflow-x-auto">
                        <table className="table font-normal">
                            <tbody>
                                <tr>
                                    <td colSpan={8}>
                                        <div className="flex justify-between items-center">
                                            <img
                                                src="/img/logo/logo.png"
                                                width={300}
                                                alt=""
                                            />
                                            <h3>
                                                <b>Raw Material In Note</b>
                                            </h3>
                                            <img
                                                src="/img/logo/eatetg.png"
                                                width={70}
                                                alt=""
                                                className="mr-3"
                                            />
                                        </div>
                                    </td>
                                </tr>
                                <tr>
                                    <td colSpan={4}>
                                        <h6>Vendor</h6>
                                        <p>
                                            {voucherData.vendor.vendor_name}
                                            <br />
                                            {voucherData.vendor.address +
                                                ','}{' '}
                                            <br />
                                            {voucherData.vendor.city +
                                                ', ' +
                                                voucherData.vendor.state +
                                                ', ' +
                                                voucherData.vendor.pincode}{' '}
                                            <br />
                                        </p>
                                    </td>
                                    <td colSpan={4}>
                                        <h6>GSTIN:</h6>
                                        <p>{voucherData.vendor.gst_number}</p>
                                    </td>
                                </tr>
                                <tr>
                                    <td colSpan={4}>
                                        <h6>P.O. No.</h6>
                                        <p>{pVoucherData.po_no}</p>
                                    </td>
                                    <td colSpan={4}>
                                        <h6>Dated</h6>
                                        <p>
                                            <Moment format="DD-MM-YYYY">
                                                {
                                                    pVoucherData.date_of_processing
                                                }
                                            </Moment>
                                        </p>
                                    </td>
                                </tr>
                                <tr>
                                    <td colSpan={4}>
                                        <div className="w-full">
                                            <h6>RIN No.</h6>
                                            <p>
                                                {voucherData.raw_material_in_no}
                                            </p>
                                        </div>
                                    </td>
                                    <td colSpan={4}>
                                        <h6>Dated</h6>
                                        <p>
                                            <Moment format="DD-MM-YYYY">
                                                {voucherData.date_of_receipt}
                                            </Moment>
                                        </p>
                                    </td>
                                </tr>
                                <tr>
                                    <td colSpan={4}>
                                        <h6>Invoice No.</h6>
                                        <p>{pVoucherData.invoice_no}</p>
                                    </td>
                                    <td colSpan={4}>
                                        <h6>Dated</h6>
                                        <p>
                                            <Moment format="DD-MM-YYYY">
                                                {pVoucherData.invoice_date}
                                            </Moment>
                                        </p>
                                    </td>
                                </tr>
                                <tr className="text-center font-semibold bg-orange-100">
                                    <td colSpan={8}>As Per PO</td>
                                </tr>
                                <tr className="text-center font-semibold">
                                    <td>Sr. No.</td>
                                    <td width={300}>Item</td>
                                    <td>Discount</td>
                                    <td>Qty</td>
                                    <td>Rate</td>
                                    <td>Amount</td>
                                    <td>GST</td>
                                    <td>Total</td>
                                </tr>
                                {/* Loop Through this <tr> */}
                                {voucherData.rawMaterialInItems.map(
                                    (value, index) => (
                                        <tr key={index}>
                                            <td>{index + 1}</td>
                                            <td>
                                                {value.raw_material.rm_name}
                                            </td>
                                            <td>0%</td>
                                            <td>{value.po_quantity}</td>
                                            <td>
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.po_rate}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                            <td>
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.po_amount}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                            <td>
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.po_tax_amt}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                            <td>
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.po_total_amt}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                        </tr>
                                    )
                                )}

                                <tr>
                                    <td colSpan={8}>
                                        <b>Other Charges As Per PO</b>
                                    </td>
                                    {/* <td>{voucherData.othe}</td> */}
                                    {/* <td colSpan={5}></td> */}
                                    {/* <td>{voucherData.round_off_amt}</td> */}
                                </tr>

                                {voucherData.rawMaterialInOtherCharges.map(
                                    (value, index) => (
                                        <tr key={index}>
                                            <td>{index + 1}</td>
                                            <td colSpan={4}>
                                                {value.item_desc}
                                            </td>
                                            <td>
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.po_amount}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                            <td>
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.po_tax_amt}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                            <td>
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.po_total_amt}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                        </tr>
                                    )
                                )}
                                <tr>
                                    <td
                                        colSpan={8}
                                        style={{
                                            border: 'none',
                                            borderTop: '1px solid #333',
                                        }}
                                    >
                                        <p className="m-3"></p>
                                    </td>
                                </tr>
                                <tr className="text-center font-semibold bg-orange-100">
                                    <td colSpan={8}>As Per RIN</td>
                                </tr>
                                <tr className="text-center font-semibold">
                                    <td>Sr. No.</td>
                                    <td width={300}>Item</td>
                                    <td>Discount</td>
                                    <td>Qty</td>
                                    <td>Rate</td>
                                    <td>Amount</td>
                                    <td>GST</td>
                                    <td>Total</td>
                                </tr>

                                {voucherData.rawMaterialInItems.map(
                                    (value, index) => (
                                        <tr key={index}>
                                            <td>{index + 1}</td>
                                            <td>
                                                {value.raw_material.rm_name}
                                            </td>
                                            <td>
                                                {value.discount == null
                                                    ? 0 + '%'
                                                    : value.discount + '%'}
                                            </td>
                                            <td>{value.qty}</td>
                                            <td>
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.rate}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                            <td>
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.amount}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                            <td>
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.tax_amt}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                            <td
                                                className={
                                                    value.po_total_amt !==
                                                    value.total_amt
                                                        ? 'bg-rose-400'
                                                        : ' bg-white'
                                                }
                                            >
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.total_amt}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                        </tr>
                                    )
                                )}
                                {/* Loop Through this </tr> */}
                                <tr>
                                    <td colSpan={8}>
                                        <b>Other Charges As Per RIN</b>
                                    </td>
                                    {/* <td>{voucherData.othe}</td> */}
                                    {/* <td colSpan={5}></td> */}
                                    {/* <td>{voucherData.round_off_amt}</td> */}
                                </tr>
                                {voucherData.rawMaterialInOtherCharges.map(
                                    (value, index) => (
                                        <tr key={index}>
                                            <td>{index + 1}</td>
                                            <td colSpan={4}>
                                                {value.item_desc}
                                            </td>
                                            <td>
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.amount}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                            <td>
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.tax_amt}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                            <td>
                                                <NumberFormat
                                                    displayType="text"
                                                    prefix={'₹'}
                                                    thousandsGroupStyle={'lakh'}
                                                    decimalScale={2}
                                                    value={value.total_amt}
                                                    allowLeadingZeros
                                                    thousandSeparator=","
                                                />
                                            </td>
                                        </tr>
                                    )
                                )}
                                <tr>
                                    <td
                                        colSpan={8}
                                        style={{
                                            border: 'none',
                                            borderTop: '1px solid #333',
                                        }}
                                    >
                                        <p className="m-3"></p>
                                    </td>
                                </tr>
                                <tr>
                                    <td colSpan={4}>
                                        <b>Summary</b>
                                    </td>
                                    <td
                                        colSpan={4}
                                        rowSpan={8}
                                        style={{
                                            borderRight: 'none',
                                            borderTop: 'none',
                                            borderBottom: 'none',
                                        }}
                                    ></td>
                                </tr>
                                <tr>
                                    <td colSpan={2}>Total : </td>
                                    <td colSpan={2}>
                                        <NumberFormat
                                            displayType="text"
                                            prefix={'₹'}
                                            thousandsGroupStyle={'lakh'}
                                            decimalScale={2}
                                            value={voucherData.amt}
                                            allowLeadingZeros
                                            thousandSeparator=","
                                        />
                                    </td>
                                </tr>
                                <tr>
                                    <td colSpan={2}>GST Amount : </td>
                                    <td colSpan={2}>
                                        <NumberFormat
                                            displayType="text"
                                            prefix={'₹'}
                                            thousandsGroupStyle={'lakh'}
                                            decimalScale={2}
                                            value={voucherData.tax_amt}
                                            allowLeadingZeros
                                            thousandSeparator=","
                                        />
                                    </td>
                                </tr>
                                <tr>
                                    <td colSpan={2}>Gross Amount : </td>
                                    <td colSpan={2}>
                                        <NumberFormat
                                            displayType="text"
                                            prefix={'₹'}
                                            thousandsGroupStyle={'lakh'}
                                            decimalScale={2}
                                            value={voucherData.total_amt}
                                            allowLeadingZeros
                                            thousandSeparator=","
                                        />
                                    </td>
                                </tr>
                                <tr>
                                    <td colSpan={2}>TDS % : </td>
                                    <td colSpan={2}>
                                        <Input
                                            type="number"
                                            placeholder="TDS %"
                                            layout="vertical"
                                            className="mb-0"
                                            size="sm"
                                            suffix="%"
                                            value={tds}
                                            onChange={(e) => {
                                                calcTDS(e)
                                            }}
                                        />
                                    </td>
                                </tr>
                                <tr>
                                    <td colSpan={2}>TDS Amount : </td>
                                    <td colSpan={2}>
                                        <NumberFormat
                                            displayType="text"
                                            prefix={'₹'}
                                            thousandsGroupStyle={'lakh'}
                                            decimalScale={2}
                                            value={pVoucherData.tdsamount}
                                            allowLeadingZeros
                                            thousandSeparator=","
                                        />
                                    </td>
                                </tr>
                                <tr>
                                    <td colSpan={2}>Round Off Amount : </td>
                                    <td colSpan={2}>
                                        <Input
                                            type="number"
                                            placeholder="TDS %"
                                            layout="vertical"
                                            className="mb-0"
                                            size="sm"
                                            prefix="₹"
                                            value={roundOff}
                                            onChange={(e) => {
                                                calcRoundOff(e)
                                            }}
                                        />
                                    </td>
                                </tr>
                                <tr style={{ borderBottom: 'none' }}>
                                    <td
                                        colSpan={2}
                                        style={{
                                            borderBottom: '1px solid #333',
                                        }}
                                    >
                                        Net Amount :{' '}
                                    </td>
                                    <td
                                        colSpan={2}
                                        style={{
                                            borderBottom: '1px solid #333',
                                        }}
                                    >
                                        <NumberFormat
                                            displayType="text"
                                            prefix={'₹'}
                                            thousandsGroupStyle={'lakh'}
                                            decimalScale={2}
                                            value={pVoucherData.total_payable}
                                            allowLeadingZeros
                                            thousandSeparator=","
                                        />
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                    <div className="border h-[500px] overflow-y-auto w-full">
                        2
                    </div>
                </div>
            </AdaptableCard>
            <StickyFooter
                className="-mx-1 md:-mx-1 px-8 flex items-center justify-between py-4"
                stickyClass="border bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700"
            >
                <div>
                    <Button
                        size="sm"
                        type="button"
                        onClick={() => approved()}
                        className="ltr:mr-6 rtl:ml-6"
                        variant="solid"
                        color="emerald-600"
                    >
                        Approve
                    </Button>
                    <Button
                        size="sm"
                        type="button"
                        variant="solid"
                        onClick={() => rejected()}
                        color="red-600"
                        className="ltr:mr-3 rtl:ml-3"
                    >
                        Reject
                    </Button>
                </div>
                <Button
                    size="sm"
                    type="button"
                    onClick={() => navigate('/transaction/finance-voucher')}
                >
                    Discard
                </Button>
            </StickyFooter>
        </>
    )
}

export default AddEditFinanceVoucher
